#!/bin/bash
# Task 127-w5-controller-speed -- meshsim sim/ WORKER5 (branch sim-w5 8738cfd). TIMING TASK: keep the box quiet while it runs.
# The RV32 controller on W3's engine (D13 pinned to CPU 0, a P-core; D18 clang release):
#   1. sanity: the 67 golden traces on the direct driver and on the engine (all must match);
#   2. bench_controller: a 13-cycle loop (9 instructions: data load/store, ALU, a multiply, a register-block load, a taken
#      branch), 10^7 iterations, booted as hello: the engine untraced (3 reps), the plain core alone (3 reps), the engine
#      traced (10^6 iterations, 3 reps); perf stat on each;
#   3. golden --bench 300: the 67 short programs (cold start included);
#   4. perf record (flat, by symbol): the plain build, a UNITS_PROFILE build (the core's step and interpreter kept out of
#      line), and the traced run; the top 40 symbols of each.
# From an embedded kit (sim/ at 8738cfd: Makefile, src, tests, fw, the boot ROM, the riscv-tests images). Expected ~5 min.
# Writes only results/127-w5-controller-speed/. Scratch in /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/127-w5-controller-speed; mkdir -p "$RES"
W=/tmp/w5-127; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "94a34c753362873baf70335764054628c849e4eeaf4fd0378c4316197fb8b21b" ] || { echo "kit sha256 mismatch (want 94a34c753362873baf70335764054628c849e4eeaf4fd0378c4316197fb8b21b)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
EV=cycles,instructions,branch-misses,cache-misses,L1-dcache-load-misses
pstat() { local tag=$1; shift; taskset -c 0 perf stat -x, -e $EV -o "$W/stat-$tag.csv" -- "$@"; local rc=$?; echo "-- perf stat $tag (rc $rc)"; grep -v '^#' "$W/stat-$tag.csv" | grep -v '^$' | tee "$RES/perf-stat-$tag.csv"; return $rc; }
prof() { local tag=$1; shift; taskset -c 0 perf record -q -F 4000 -o "$W/perf-$tag.data" -- "$@" > "$W/prof-$tag.out" 2>&1; echo "-- perf record $tag (rc $?)"; cat "$W/prof-$tag.out"; perf report -i "$W/perf-$tag.data" --stdio --no-children --sort symbol 2>/dev/null | grep -v '^#' | grep -v '^$' | head -40 | tee "$RES/perf-report-$tag.txt"; }
START=$(date +%s)
{
sec "machine"; uname -r; nproc; lscpu | grep -E 'Model name|^CPU\(s\)|Thread'; uptime
echo "cpu0 siblings: $(cat /sys/devices/system/cpu/cpu0/topology/thread_siblings_list 2>/dev/null)"
echo "cpu0 max MHz: $(cat /sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq 2>/dev/null)"
clang++ --version | head -1
cd "$W/kit/sim" || exit 2
sec "build (clang release; and a UNITS_PROFILE copy with -g)"
make -j8 CC_NAME=clang MODE=release build/clang-release/golden build/clang-release/bench_controller > "$RES/build.log" 2>&1 \
  || { tail -20 "$RES/build.log"; verdict "build" FAIL; }
cp -r "$W/kit/sim" "$W/prof"; rm -rf "$W/prof/build"
( cd "$W/prof" && make -j8 CC_NAME=clang MODE=release RELEASE="-O2 -DNDEBUG -g -fno-omit-frame-pointer -DUNITS_PROFILE" \
  build/clang-release/bench_controller ) > "$RES/build-prof.log" 2>&1 || { tail -20 "$RES/build-prof.log"; verdict "profile build" FAIL; }
rm -rf "$W/plain"; cp -r "$W/kit/sim" "$W/plain"; rm -rf "$W/plain/build"
( cd "$W/plain" && make -j8 CC_NAME=clang MODE=release RELEASE="-O2 -DNDEBUG -g -fno-omit-frame-pointer" \
  build/clang-release/bench_controller ) > "$RES/build-plain-g.log" 2>&1 || { tail -20 "$RES/build-plain-g.log"; verdict "plain -g build" FAIL; }
B=build/clang-release
sec "1. the 67 goldens: direct driver and engine"
$B/golden --direct | tail -1; $B/golden --engine > "$W/g.txt"; tail -2 "$W/g.txt"
grep -q ' 0 differ' "$W/g.txt" && verdict "67 goldens on the engine" PASS || { grep -v '^SAME' "$W/g.txt" | head -40; verdict "67 goldens on the engine" FAIL; }
sec "2a. bench_controller: the engine, untraced, 10^7 iterations, 3 reps"
pstat engine $B/bench_controller --iters 10000000 --reps 3 --only engine | tee "$RES/bench-engine.txt"
sec "2b. bench_controller: the plain core alone, 10^7 iterations, 3 reps"
pstat core $B/bench_controller --iters 10000000 --reps 3 --only core | tee "$RES/bench-core.txt"
sec "2c. bench_controller: the engine, traced, 10^6 iterations, 3 reps"
pstat traced $B/bench_controller --iters 1000000 --reps 3 --only engine --trace | tee "$RES/bench-traced.txt"
grep -q 'DID NOT HALT' "$RES"/bench-*.txt && verdict "every bench run halts by SIM_EXIT" FAIL || verdict "every bench run halts by SIM_EXIT" PASS
sec "3. golden --bench 300 (the 67 short programs, cold start included)"
taskset -c 0 $B/golden --bench 300 | tee "$RES/bench-goldens.txt"
sec "4a. perf record: the plain build (-g), engine untraced, 10^7 iterations"
prof plain "$W/plain/$B/bench_controller" --iters 10000000 --reps 1 --only engine
sec "4b. perf record: the UNITS_PROFILE build (the core's step and interpreter out of line), engine untraced"
prof noinline "$W/prof/$B/bench_controller" --iters 10000000 --reps 1 --only engine
sec "4c. perf record: the UNITS_PROFILE build, engine traced, 10^6 iterations"
prof traced "$W/prof/$B/bench_controller" --iters 1000000 --reps 1 --only engine --trace
sec "4d. perf record: the UNITS_PROFILE build, the core alone"
prof core "$W/prof/$B/bench_controller" --iters 10000000 --reps 1 --only core
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
